'use strict';
(async()=>{
 const $=id=>document.getElementById(id),B=window.VisualReferences,page=window.REFERENCES_PAGE_MODE===true,base=window.ATLAS_ASSET_BASE||'';
 const esc=v=>String(v||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const norm=v=>String(v).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
 let data;try{data=window.REFERENCE_CATALOG||(window.REFERENCE_CATALOG_PROMISE?await window.REFERENCE_CATALOG_PROMISE:null)||await fetch(base+'visual-references.json').then(r=>{if(!r.ok)throw Error();return r.json()})}catch{$('refCount').textContent='Não foi possível carregar as referências. Recarregue a página.';return}
 const all=data.references,byId=new Map(all.map(x=>[x.id,x]));let selection=[],favorites=new Set(),category='',favOnly=false,limit=24,timer;
 if(page){selection=B.clean(window.openai?.widgetState?.modelContent?.visualReferences);const bits=window.openai?.widgetState?.privateContent?.favoriteBits||'';favorites=new Set(all.filter((x,i)=>bits[i]==='1').map(x=>x.id))}else{selection=B.read();try{favorites=new Set(JSON.parse(localStorage.getItem('gda-reference-favorites-v1')||'[]'))}catch{}}
 selection=selection.filter(x=>byId.has(x.id));
 const toast=msg=>{$('refToast').textContent=msg;$('refToast').classList.add('show');clearTimeout(timer);timer=setTimeout(()=>$('refToast').classList.remove('show'),4000)};
 async function persist(){if(page){if(!window.openai?.setWidgetState){toast('Esta superfície não permite salvar. Copie a direção visual.');return false}try{await window.openai.setWidgetState({modelContent:{visualReferences:B.clean(selection),referencePolicy:'Usar somente os aspectos selecionados. Confirmar acesso às imagens. Marca e referências originais têm prioridade; não copiar ativos de terceiros.'},privateContent:{favoriteBits:all.map(x=>favorites.has(x.id)?'1':'0').join('')}});return true}catch{toast('Não foi possível salvar a seleção. Copie a direção visual.');return false}}const ok=B.write(selection);try{localStorage.setItem('gda-reference-favorites-v1',JSON.stringify([...favorites]))}catch{}if(!ok)toast('O navegador não salvou a seleção. Copie a direção visual antes de sair.');return ok}
 const swatches=x=>`<span class="ref-swatches" aria-label="Cores aproximadas da capa: ${esc(x.palette.join(', '))}">${x.palette.map(c=>`<i style="background:${c}" title="${c}"></i>`).join('')}</span>`;
 function render(){const q=norm($('refSearch').value),items=all.filter(x=>(!category||x.categories.includes(category))&&(!favOnly||favorites.has(x.id))&&(!q||norm([x.title,x.author,x.category,...x.tags,...x.palette].join(' ')).includes(q)));$('refCount').textContent=`${items.length} referências${category?' · '+category:''}`;$('refEmpty').hidden=items.length>0;$('refMore').hidden=items.length<=limit;$('refFavorites').setAttribute('aria-pressed',favOnly);$('refCategories').innerHTML=['',...data.categories].map(c=>`<button class="family${category===c?' active':''}" data-category="${esc(c)}" aria-pressed="${category===c}">${esc(c||'Todas')} <small>${c?all.filter(x=>x.categories.includes(c)).length:all.length}</small></button>`).join('');$('refGrid').innerHTML=items.slice(0,limit).map(x=>{const chosen=selection.some(s=>s.id===x.id);return `<article class="ref-card${chosen?' selected':''}"><button class="ref-image-button" data-detail="${x.id}" aria-label="Abrir ${esc(x.title)}"><img src="${esc(x.image)}" alt="Capa do projeto ${esc(x.title)}" loading="lazy" decoding="async" referrerpolicy="no-referrer"></button><button class="ref-favorite" data-fav="${x.id}" aria-label="Favoritar ${esc(x.title)}" aria-pressed="${favorites.has(x.id)}">${favorites.has(x.id)?'♥':'♡'}</button><div class="ref-card-body"><h3>${esc(x.title)}</h3><p class="small">${esc(x.category)}</p><div class="ref-card-bottom">${swatches(x)}<button class="ref-toggle" data-select="${x.id}" aria-pressed="${chosen}"><span aria-hidden="true">${chosen?'✓':''}</span>${chosen?'Selecionada':'Selecionar'}</button></div></div></article>`}).join('');wireImageErrors();}
 function wireImageErrors(){document.querySelectorAll('.ref-image-button img').forEach(img=>img.addEventListener('error',()=>{const p=img.parentElement;img.remove();const msg=document.createElement('span');msg.className='ref-failure';msg.textContent='Imagem indisponível · abrir ficha';p.append(msg)},{once:true}))}
 function panel(){ if($('mobileRefCount'))$('mobileRefCount').textContent=selection.length;$('refSelection').innerHTML=selection.length?selection.map(x=>`<div class="ref-selected"><div class="ref-selected-head"><img src="${esc(x.image)}" alt="" referrerpolicy="no-referrer"><strong>${esc(x.title)}</strong><button data-remove="${x.id}" aria-label="Remover ${esc(x.title)}">×</button></div><div class="ref-roles">${Object.entries(B.roles).map(([k,v])=>`<label><input type="checkbox" data-role="${k}" data-id="${x.id}" ${x.roles.includes(k)?'checked':''}>${v}</label>`).join('')}</div></div>`).join(''):'<p class="small">Seu painel está vazio. Comece por uma imagem que combine com sua ideia.</p>';$('refPreview').textContent=selection.length?selection.map(x=>`${x.title}: ${x.roles.map(r=>B.roles[r].toLowerCase()).join(', ')}${x.roles.includes('palette')?' ('+x.palette.join(' · ')+')':''}.`).join('\n\n'):'Selecione uma referência e defina seu papel no vídeo.';$('refAdd').disabled=!selection.length;$('refCopy').disabled=!selection.length;}
 async function toggle(id){const i=selection.findIndex(x=>x.id===id);if(i>=0)selection.splice(i,1);else{if(selection.length>=6){toast('Escolha até 6 referências. Remova uma para adicionar outra.');return}const x=byId.get(id);selection.push({...B.clean([{...x,roles:['composition']}])[0]})}await persist();panel();render()}
 function detail(id){const x=byId.get(id);$('refDetailBody').innerHTML=`<img src="${esc(x.image)}" alt="Capa de ${esc(x.title)}" referrerpolicy="no-referrer"><p class="eyebrow">${esc(x.category)}</p><h2>${esc(x.title)}</h2><p>Projeto de <strong>${esc(x.author)}</strong></p>${swatches(x)}<p class="small">Paleta aproximada extraída automaticamente da capa. A tipografia deve ser analisada no projeto original; nomes de fontes não foram inferidos.</p><p>${esc(x.guidance)}</p><div class="actions"><button class="primary" data-select="${x.id}">${selection.some(s=>s.id===id)?'Remover da direção':'Selecionar referência'}</button><a class="button outline" href="${esc(x.url)}" target="_blank" rel="noopener noreferrer">Ver projeto original ↗</a></div><p class="ref-license">Imagem carregada da fonte original. Direitos dos respectivos autores. Condição informada na fonte: ${esc(x.license||'consultar projeto')}. Acesso público não concede licença de reutilização. Consulte o autor antes de incorporar ativos.</p>`;$('refDetail').showModal();}
 $('refGrid').addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;const id=b.dataset.fav;if(id){favorites.has(id)?favorites.delete(id):favorites.add(id);await persist();b.setAttribute('aria-pressed',favorites.has(id));b.textContent=favorites.has(id)?'♥':'♡';if(favOnly)render()}else if(b.dataset.detail)detail(b.dataset.detail);else if(b.dataset.select)toggle(b.dataset.select)});
 $('refDetailBody').addEventListener('click',e=>{const b=e.target.closest('[data-select]');if(b){toggle(b.dataset.select);$('refDetail').close()}});$('refClose').onclick=()=>$('refDetail').close();$('refCategories').onclick=e=>{const b=e.target.closest('[data-category]');if(b){category=b.dataset.category;limit=24;render()}};$('refSearch').oninput=()=>{limit=24;render()};$('refFavorites').onclick=()=>{favOnly=!favOnly;limit=24;render()};$('refMore').onclick=()=>{limit+=24;render()};
 $('refSelection').onclick=e=>{const b=e.target.closest('[data-remove]');if(b)toggle(b.dataset.remove)};$('refSelection').onchange=async e=>{const el=e.target;if(!el.dataset.role)return;const x=selection.find(x=>x.id===el.dataset.id);if(el.checked)x.roles.push(el.dataset.role);else if(x.roles.length===1){el.checked=true;toast('Mantenha ao menos um aspecto por referência.');return}else x.roles=x.roles.filter(r=>r!==el.dataset.role);await persist();panel()};
 $('refCopy').onclick=async()=>{try{await navigator.clipboard.writeText(B.text(selection));toast('Direção copiada. Cole junto ao pedido do vídeo no ChatGPT.')}catch{const area=document.createElement('textarea');area.value=B.text(selection);area.rows=12;area.setAttribute('aria-label','Direção visual para copiar');$('refSelection').append(area);area.select();toast('Selecione e copie o texto exibido.')}};
 $('refAdd').onclick=async()=>{if(!await persist())return;if(page)toast('Referências salvas nesta página. Use o comando de produção para combinar com o briefing.');else location.href='index.html?brief=1'};
 if(page){$('refAdd').textContent='Salvar direção nesta página';$('refPersistence').textContent='A seleção salva acompanha esta página do ChatGPT. O comando de produção deve ler a direção e o briefing.';$('fullBriefLink').href='https://videos.gerenciadordeanuncios.com.br/';window.addEventListener('openai:set_globals',e=>{if(e.detail?.globals?.widgetState){selection=B.clean(e.detail.globals.widgetState.modelContent?.visualReferences).filter(x=>byId.has(x.id));const bits=e.detail.globals.widgetState.privateContent?.favoriteBits||'';favorites=new Set(all.filter((x,i)=>bits[i]==='1').map(x=>x.id));panel();render()}})}else{try{const s=JSON.parse(localStorage.getItem('video-multimarcas-atlas-v1')||'null');$('currentStyle').textContent=s?.modelContent?.selectedStyles?.length?'Estilo: '+s.modelContent.selectedStyles.map(x=>x.name).join(' + '):'Combine a direção com um estilo de vídeo no pedido.'}catch{}}
 panel();render();window.REFERENCES_READY=true;
})();
